with scored as (select *, min(duration_sec) over w_part as running_min_duration_sec, avg(duration_sec) over w_part as running_avg_duration_sec, sum(duration_sec) over w_part as running_sum_duration_sec from web_events where page in ('/home', '/search', '/checkout') window w_part as (partition by session_id order by event_time, id rows between unbounded preceding and current row)) select date_trunc('quarter', event_time) as quarter_start, min(event_time) as first_event_time, sum(case when event_type = 'add_to_cart' then running_min_duration_sec else 0 end) as add_to_cart_running_min_duration_sec, round(avg(running_sum_duration_sec), 2) as avg_running_sum_duration_sec from scored group by date_trunc('quarter', event_time) order by avg_running_sum_duration_sec desc;
